// 把二维数组转成 CSV（RFC 4180 转义，见 README）。
// 字段里含 , " 或换行（含 \r）时用双引号包住，内部 " 写成 ""；行尾用 \n 且不留尾随换行。

const NEEDS_QUOTE = /[",\r\n]/;

function escapeField(value) {
  const s = value == null ? "" : String(value);
  if (!NEEDS_QUOTE.test(s)) return s;
  return '"' + s.replace(/"/g, '""') + '"';
}

export function toCsv(rows) {
  return rows.map((r) => r.map(escapeField).join(",")).join("\n");
}

import test from "node:test";
import assert from "node:assert/strict";
import { toCsv } from "../src/export.js";
import { exportUsers } from "../src/report.js";

// 边界用例（不重复 tests/export.test.js 已覆盖的 , " \n 基本转义）

test("含 CRLF 的字段也要包起来（换行含回车）", () => {
  assert.equal(toCsv([["a\r\nb", "x"]]), '"a\r\nb",x');
});

test("单独的回车也按换行处理", () => {
  assert.equal(toCsv([["a\rb"]]), '"a\rb"');
});

test("引号与逗号同时出现：先翻倍再包裹", () => {
  assert.equal(toCsv([['a,"b"', "c"]]), '"a,""b""",c');
});

test("整表输出无尾随换行", () => {
  const out = toCsv([["a", "b"], ["c,d", "e"]]);
  assert.equal(out, 'a,b\n"c,d",e');
  assert.ok(!out.endsWith("\n"));
});

test("字段内换行被包裹，行数不被撑开", () => {
  const out = toCsv([["a\nb", "c"], ["d", "e"]]);
  assert.equal(out.split("\n").length, 2);
  assert.equal(out, '"a\nb",c\nd,e');
});

test("空输入返回空串，不产生裸换行", () => {
  assert.equal(toCsv([]), "");
  assert.equal(toCsv([[]]), "");
});

test("数字与空值字段不误加引号", () => {
  assert.equal(toCsv([[1, null, undefined, "x"]]), '1,,,x');
});

test("report 导出：note 含逗号与引号时转义生效", () => {
  const out = exportUsers([{ id: 7, name: 'He said "hi"', note: "x,y" }]);
  assert.equal(out, 'id,name,note\n7,"He said ""hi""","x,y"');
});

test("report 导出：无特殊字符时保持朴素，且末尾无换行", () => {
  const out = exportUsers([{ id: 1, name: "ann", note: null }]);
  assert.equal(out, "id,name,note\n1,ann,");
  assert.ok(!out.endsWith("\n"));
});

