  const out = toCsv([["a\nb", "c"], ["d", "e"]]);
  assert.equal(out, '"a\nb",c\nd,e');
  // 物理换行数 = 字段内 1 + 行分隔 1；解析时按引号配对，字段内的换行属于数据而非行边界
  assert.equal(out.split("\n").length, 3);
});
